//! Hostile test plugin: a component for another major version of the WIT
//! package (`jellyfesh:plugin@2.0.0`), packed with a manifest that claims
//! `api_version = "1.0"`. The host must refuse it when it links the
//! component, whatever the manifest says.

#[allow(unsafe_code, reason = "canonical ABI glue generated by wit-bindgen")]
mod bindings {
    wit_bindgen::generate!({
        inline: r#"
            package jellyfesh:plugin@2.0.0;

            interface meta {
                capabilities: func() -> list<string>;
            }

            interface log {
                log: func(message: string);
            }

            world source {
                import log;
                export meta;
            }
        "#,
        world: "source",
    });
}

struct Mismatch;

impl bindings::exports::jellyfesh::plugin::meta::Guest for Mismatch {
    fn capabilities() -> Vec<String> {
        bindings::jellyfesh::plugin::log::log("hello from 2.0");
        vec!["search".into()]
    }
}

#[cfg(target_arch = "wasm32")]
#[allow(unsafe_code, reason = "canonical ABI glue generated by wit-bindgen")]
const _: () = {
    bindings::export!(Mismatch with_types_in bindings);
};
